package com.agacostays.payment.config;
import org.apache.kafka.clients.producer.ProducerConfig; import org.apache.kafka.common.serialization.StringSerializer; import org.springframework.boot.autoconfigure.kafka.KafkaProperties; import org.springframework.context.annotation.*; import org.springframework.kafka.core.*; import org.springframework.kafka.support.serializer.JacksonJsonSerializer; import java.util.*;
@Configuration public class KafkaProducerConfig { @Bean ProducerFactory<String,Object> producerFactory(KafkaProperties p){Map<String,Object> m=new HashMap<>(p.buildProducerProperties());m.put(ProducerConfig.KEY_SERIALIZER_CLASS_CONFIG,StringSerializer.class);m.put(ProducerConfig.VALUE_SERIALIZER_CLASS_CONFIG,JacksonJsonSerializer.class);return new DefaultKafkaProducerFactory<>(m);} @Bean KafkaTemplate<String,Object> kafkaTemplate(ProducerFactory<String,Object> pf){return new KafkaTemplate<>(pf);} }
